// Set timestamp for the test page
        const updateTimestamp = () => {
            document.getElementById('print-timestamp').innerText = "GENERATED: " + new Date().toLocaleString().toUpperCase();
        };
        // Print listener to hide UI if user uses Ctrl+P
        window.onbeforeprint = updateTimestamp;
        // Initialize Scroll to Top logic
        // Auto-update timestamp on load
        document.addEventListener('DOMContentLoaded', updateTimestamp);
